content.content:
1	/* PhishSense colors: navy + teal, matching the logo */
2	:root {
3	  --navy: #0a1a33;
4	  --navy-2: #123a5c;
5	  --teal: #2de0c4;
6	  --text: #e9f1f7;
7	  --muted: #9fb7c9;
8	  --red: #ff5d6c;
9	  --green: #3ddc84;
10	  /* Difficulty colors: buttons, badge icons, mission title */
11	  --easy: #4ade80;     /* Minnow */
12	  --medium: #facc15;   /* Angler */
13	  --hard: #f87171;     /* Captain */
14	  --easy-tint: rgba(74, 222, 128, 0.14);
15	  --medium-tint: rgba(250, 204, 21, 0.14);
16	  --hard-tint: rgba(248, 113, 113, 0.14);
17	  --fit-h: none; /* set on large screens: the height a screen must fit in */
18	}
19	
20	* { box-sizing: border-box; }
21	
22	/* ---------- Bootstrap overrides ----------
23	   Bootstrap is loaded for its grid only. Its base styles ("reboot") change
24	   fonts, spacing, and headings, so these put our original look back. */
25	:root { scroll-behavior: auto; }   /* the link popup measures right after scrolling */
26	body {
27	  margin: 0;
28	  font-family: "Inter", Arial, sans-serif;
29	  font-size: 1rem;   /* 16px; grows a little on very wide screens (see below) */
30	  line-height: normal;
31	  background: var(--navy);
32	  color: var(--text);
33	}
34	h1, h2, h3 { color: inherit; font-weight: bold; line-height: normal; }
35	h2 { font-size: 1.5em; margin: 0.83em 0; }
36	h3 { font-size: 1.17em; margin: 1em 0; }
37	p { margin: 1em 0; }
38	ul, ol { margin: 1em 0; padding-left: 40px; }
39	small { font-size: smaller; }
40	.container { max-width: 1200px; }   /* one width at every breakpoint, centered */
41	
42	/* ---------- Headers ---------- */
43	/* Big centered header on the home screen */
44	.hero { text-align: center; padding: 32px 16px 8px; }
45	.hero h1 { margin: 0; font-size: 44px; font-weight: 800; }
46	.hero h1 span { color: var(--teal); }
47	.logo { width: 120px; height: auto; display: block; margin: 0 auto 8px; }
48	.tagline { margin: 4px 0 0; color: var(--muted); letter-spacing: 3px; text-transform: uppercase; font-size: 13px; }
49	
50	/* Slim top bar on every other screen */
51	.topbar { display: none; border-bottom: 1px solid rgba(159, 183, 201, 0.15); background: #0c1f3b; }
52	body:not([data-screen="start-screen"]) .hero { display: none; }
53	body:not([data-screen="start-screen"]) .topbar { display: block; }
54	.topbar-inner {
55	  padding-top: 8px; padding-bottom: 8px; min-height: 52px;
56	  display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 8px 16px;
57	}
58	.brand { display: flex; align-items: center; gap: 10px; }
59	.brand-logo { width: 36px; height: 36px; display: block; }
60	.brand-name { font-size: 20px; font-weight: 800; }
61	.brand-name span { color: var(--teal); }
62	
63	/* Run status: shown while playing, and as a final summary on the end screen */
64	.run-status { display: none; flex-wrap: wrap; align-items: center; gap: 8px 14px; margin-left: auto; }
65	body[data-screen="play-screen"] .run-status,
66	body[data-screen="end-screen"] .run-status { display: flex; }
67	body[data-screen="end-screen"] .streak,
68	body[data-screen="end-screen"] .run-tools { display: none; }
69	/* Mission screen: the bar shows only the "?" (replay tutorial); other screens hide the "?" */
70	body[data-screen="mission-screen"] .run-status { display: flex; }
71	body[data-screen="mission-screen"] .run-info,
72	body[data-screen="mission-screen"] .streak,
73	body[data-screen="mission-screen"] .contacts-toggle,
74	body:not([data-screen="mission-screen"]) .help-toggle { display: none; }
75	.run-info { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 14px; }
76	.round-counter { margin: 0; font-size: 14px; color: var(--muted); white-space: nowrap; }
77	
78	/* ---------- Page ---------- */
79	main { padding-top: 16px; padding-bottom: 16px; }
80	body:not([data-screen="start-screen"]) main { padding-top: 32px; }   /* gap under the top bar */
81	body[data-screen="mission-screen"] main { padding-top: 20px; }   /* tighter, to make room for the big Start mission boat */
82	.hidden { display: none !important; }
83	
84	/* Home: one column on phones (name + modes, Masters, Leaderboard).
85	   900px and up: Leaderboard | name + modes | Masters. The side columns share one width,
86	   so the middle stays centered, and they sit in one grid row, so both cards start at the
87	   same top edge and stretch to the same height. */
88	.home-grid { display: grid; grid-template-columns: minmax(0, 1fr); gap: 16px; }
89	.home-center { order: 1; min-width: 0; }
90	.home-masters { order: 2; }
91	.home-board { order: 3; }
92	.home-grid > .ps-card { margin: 0; min-width: 0; display: flex; flex-direction: column; }
93	@media (min-width: 900px) {
94	  .home-grid { grid-template-columns: minmax(0, 1fr) minmax(0, 1.35fr) minmax(0, 1fr); gap: 24px; align-items: stretch; }
95	  .home-board { order: 1; }
96	  .home-center { order: 2; }
97	  .home-masters { order: 3; }
98	}
99	
100	/* Mission: two cards side by side on large screens, same height.
101	   Uses the full container width, so its edges line up with the play screen and the logo. */
102	#mission-screen .ps-card { margin: 0; }
103	/* Cards fill their column (flex, not height: 100%, so a tutorial tip placed
104	   under a card grows the column instead of spilling into the next row) */
105	#mission-screen > .col-lg-7, #mission-screen > .col-lg-5 { display: flex; flex-direction: column; }
106	#mission-screen .briefing, #mission-screen .contacts { flex: 1 1 auto; }
107	
108	/* Scroll areas inside cards get a dark scrollbar that matches the theme */
109	.ps-card, .email .body, .sms .bubble { scrollbar-width: thin; scrollbar-color: #3a6185 transparent; }
110	
111	/* Start screen */
112	.intro { text-align: center; color: var(--muted); margin: 4px 0 0; }
113	.step-label { margin: 22px 0 8px; font-weight: 600; color: var(--text); }
114	.step-label + input { margin-top: 0; }
115	/* Leaderboard and Masters rows: rank (or trophy) | name + badge icons | points.
116	   Names never wrap; a long one ends in "…" so the points stay on the same line. */
117	.leaderboard-list, .masters-list { list-style: none; padding: 0; margin: 0; }
118	.lb-row { display: grid; grid-template-columns: 1.6em minmax(0, 1fr) auto; align-items: center; gap: 8px; margin: 7px 0; }
119	.lb-rank { color: var(--muted); font-weight: 700; text-align: right; }
120	.lb-who { display: flex; align-items: center; gap: 0; min-width: 0; white-space: nowrap; }
121	.lb-name { overflow: hidden; text-overflow: ellipsis; margin-right: 4px; }
122	.lb-who .lb-badge { flex-shrink: 0; display: inline-flex; }
123	.lb-row .lb-score { color: var(--muted); white-space: nowrap; text-align: right; }
124	.leaderboard-list .empty, .masters-list .empty { color: var(--muted); }
125	/* A long Masters list scrolls inside its card instead of making the side cards taller */
126	.masters-list { max-height: 15em; overflow-y: auto; padding-right: 6px; }
127	
128	/* Masters: players who earned all three badges */
129	.masters { border: 2px solid var(--medium); }
130	.masters h3 { margin-top: 0; }
131	
132	/* "Earn all 3 badges" note, pinned to the bottom of the Masters card */
133	.master-goal { margin-top: auto; padding-top: 14px; text-align: center; color: var(--muted); font-weight: 600; }
134	.master-goal p { margin: 0 0 8px; }
135	.master-badges { display: flex; justify-content: center; gap: 14px; font-size: 1.6em; }
136	.master-badges .badge-icon { margin: 0; }
137	.master-shimmer {
138	  font-weight: 800;
139	  background: linear-gradient(100deg, var(--medium) 0%, var(--medium) 40%, #fff8d6 50%, var(--medium) 60%, var(--medium) 100%);
140	  background-size: 250% 100%;
141	  -webkit-background-clip: text; background-clip: text;
142	  color: transparent;
143	  animation: master-shimmer 2.6s linear infinite;
144	}
145	@keyframes master-shimmer {
146	  from { background-position: 100% 0; }
147	  to   { background-position: -150% 0; }
148	}
149	
150	/* Mission screen */
151	.briefing { margin-top: 0; line-height: 1.6; color: var(--muted); }
152	.briefing p { margin: 0 0 10px; }
153	.briefing p:last-child { margin-bottom: 0; }
154	.briefing b { color: var(--text); }
155	.briefing-title { font-size: 13px; font-weight: 600; letter-spacing: 2px; text-transform: uppercase; color: var(--teal) !important; }
156	.mission-mode { font-size: 20px; font-weight: 800; color: var(--text); }
157	.mission-mode.tier-easy, .mission-mode.tier-medium, .mission-mode.tier-hard { color: var(--tier); }
158	.facts { padding: 10px 14px; border-left: 3px solid var(--teal); background: rgba(45, 224, 196, 0.08); border-radius: 6px; }
159	.mission-buttons { display: flex; justify-content: space-between; align-items: flex-end; gap: 12px; }
160	button.secondary { background: transparent; color: var(--text); border: 2px solid var(--navy-2); }
161	
162	input {
163	  display: block; width: 100%; margin: 0; padding: 12px;
164	  border-radius: 10px; border: 1px solid var(--navy-2);
165	  background: var(--navy-2); color: var(--text); font-size: 1rem;
166	}
167	
168	button {
169	  font-family: inherit; font-size: 1rem; font-weight: 600; line-height: normal; cursor: pointer;
170	  border: none; border-radius: 10px; padding: 12px 18px;
171	  background: var(--teal); color: var(--navy);
172	}
173	button:disabled { opacity: 0.5; cursor: default; }
174	
175	/* Start mission is a little fishing boat that blinks a teal glow to draw the eye.
176	   The button itself is see-through: ::before is the hull, ::after the cabin
177	   and mast. The glow is a drop-shadow so it follows the boat's outline
178	   instead of a rectangle. It's big, so the mission screen's gaps are trimmed
179	   (see "Mission screen" below) to keep everything on one screen; the mast
180	   tip pokes a little above the button into the gap. */
181	#btn-start {
182	  position: relative; isolation: isolate;
183	  min-width: 300px; padding: 30px 64px 12px; border-radius: 0;
184	  font-size: 1.35rem; font-weight: 800; letter-spacing: 0.5px;
185	  background: transparent; color: var(--navy);
186	  animation: start-blink 1.4s ease-in-out infinite;
187	}
188	#btn-start::before { /* hull, with a darker stripe at the waterline */
189	  content: ""; position: absolute; inset: 20px 0 0 0; z-index: -1;
190	  background: linear-gradient(var(--teal) 82%, #1fa892 82%);
191	  clip-path: polygon(0 6%, 100% 0, 89% 100%, 8% 100%);
192	}
193	#btn-start::after { /* cabin with a porthole (left) and the mast (right) */
194	  content: ""; position: absolute; left: 24%; bottom: calc(100% - 20px);
195	  width: 40%; max-width: 140px; height: 30px;
196	  background:
197	    radial-gradient(circle, var(--navy-2) 3.5px, transparent 4.5px) no-repeat left calc(27% - 6px) bottom 2px / 12px 12px,
198	    linear-gradient(var(--text), var(--text)) no-repeat right 20% bottom / 4px 30px,
199	    linear-gradient(var(--text), var(--text)) no-repeat left bottom / 55% 16px;
200	}
201	#btn-start:hover, #btn-start:focus-visible { animation: none; filter: brightness(1.1) drop-shadow(0 0 10px rgba(45, 224, 196, 0.6)); }
