/* PhishSense colors: navy + teal, matching the logo */
:root {
  --navy: #0a1a33;
  --navy-2: #123a5c;
  --teal: #2de0c4;
  --text: #e9f1f7;
  --muted: #9fb7c9;
  --red: #ff5d6c;
  --green: #3ddc84;
  /* Difficulty colors: buttons, badge icons, mission title */
  --easy: #4ade80;     /* Minnow */
  --medium: #facc15;   /* Angler */
  --hard: #f87171;     /* Captain */
  --easy-tint: rgba(74, 222, 128, 0.14);
  --medium-tint: rgba(250, 204, 21, 0.14);
  --hard-tint: rgba(248, 113, 113, 0.14);
  --fit-h: none; /* set on large screens: the height a screen must fit in */
}

* { box-sizing: border-box; }

/* ---------- Bootstrap overrides ----------
   Bootstrap is loaded for its grid only. Its base styles ("reboot") change
   fonts, spacing, and headings, so these put our original look back. */
:root { scroll-behavior: auto; }   /* the link popup measures right after scrolling */
body {
  margin: 0;
  font-family: "Inter", Arial, sans-serif;
  font-size: 1rem;   /* 16px; grows a little on very wide screens (see below) */
  line-height: normal;
  background: var(--navy);
  color: var(--text);
}
h1, h2, h3 { color: inherit; font-weight: bold; line-height: normal; }
h2 { font-size: 1.5em; margin: 0.83em 0; }
h3 { font-size: 1.17em; margin: 1em 0; }
p { margin: 1em 0; }
ul, ol { margin: 1em 0; padding-left: 40px; }
small { font-size: smaller; }
.container { max-width: 1200px; }   /* one width at every breakpoint, centered */

/* ---------- Headers ---------- */
/* Big centered header on the home screen */
.hero { text-align: center; padding: 32px 16px 8px; }
.hero h1 { margin: 0; font-size: 44px; font-weight: 800; }
.hero h1 span { color: var(--teal); }
.logo { width: 120px; height: auto; display: block; margin: 0 auto 8px; }
.tagline { margin: 4px 0 0; color: var(--muted); letter-spacing: 3px; text-transform: uppercase; font-size: 13px; }

/* Slim top bar on every other screen */
.topbar { display: none; border-bottom: 1px solid rgba(159, 183, 201, 0.15); background: #0c1f3b; }
body:not([data-screen="start-screen"]) .hero { display: none; }
body:not([data-screen="start-screen"]) .topbar { display: block; }
.topbar-inner {
  padding-top: 8px; padding-bottom: 8px; min-height: 52px;
  display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 8px 16px;
}
.brand { display: flex; align-items: center; gap: 10px; }
.brand-logo { width: 36px; height: 36px; display: block; }
.brand-name { font-size: 20px; font-weight: 800; }
.brand-name span { color: var(--teal); }

/* Run status: shown while playing, and as a final summary on the end screen */
.run-status { display: none; flex-wrap: wrap; align-items: center; gap: 8px 14px; margin-left: auto; }
body[data-screen="play-screen"] .run-status,
body[data-screen="end-screen"] .run-status { display: flex; }
body[data-screen="end-screen"] .streak,
body[data-screen="end-screen"] .run-tools { display: none; }
/* Mission screen: the bar shows only the "?" (replay tutorial); other screens hide the "?" */
body[data-screen="mission-screen"] .run-status { display: flex; }
body[data-screen="mission-screen"] .run-info,
body[data-screen="mission-screen"] .streak,
body[data-screen="mission-screen"] .contacts-toggle,
body:not([data-screen="mission-screen"]) .help-toggle { display: none; }
.run-info { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 14px; }
.round-counter { margin: 0; font-size: 14px; color: var(--muted); white-space: nowrap; }

/* ---------- Page ---------- */
main { padding-top: 16px; padding-bottom: 16px; }
body:not([data-screen="start-screen"]) main { padding-top: 32px; }   /* gap under the top bar */
body[data-screen="mission-screen"] main { padding-top: 20px; }   /* tighter, to make room for the big Start mission boat */
.hidden { display: none !important; }

/* Home: one column on phones (name + modes, Masters, Leaderboard).
   900px and up: Leaderboard | name + modes | Masters. The side columns share one width,
   so the middle stays centered, and they sit in one grid row, so both cards start at the
   same top edge and stretch to the same height. */
.home-grid { display: grid; grid-template-columns: minmax(0, 1fr); gap: 16px; }
.home-center { order: 1; min-width: 0; }
.home-masters { order: 2; }
.home-board { order: 3; }
.home-grid > .ps-card { margin: 0; min-width: 0; display: flex; flex-direction: column; }
@media (min-width: 900px) {
  .home-grid { grid-template-columns: minmax(0, 1fr) minmax(0, 1.35fr) minmax(0, 1fr); gap: 24px; align-items: stretch; }
  .home-board { order: 1; }
  .home-center { order: 2; }
  .home-masters { order: 3; }
}

/* Mission: two cards side by side on large screens, same height.
   Uses the full container width, so its edges line up with the play screen and the logo. */
#mission-screen .ps-card { margin: 0; }
/* Cards fill their column (flex, not height: 100%, so a tutorial tip placed
   under a card grows the column instead of spilling into the next row) */
#mission-screen > .col-lg-7, #mission-screen > .col-lg-5 { display: flex; flex-direction: column; }
#mission-screen .briefing, #mission-screen .contacts { flex: 1 1 auto; }

/* Scroll areas inside cards get a dark scrollbar that matches the theme */
.ps-card, .email .body, .sms .bubble { scrollbar-width: thin; scrollbar-color: #3a6185 transparent; }

/* Start screen */
.intro { text-align: center; color: var(--muted); margin: 4px 0 0; }
.step-label { margin: 22px 0 8px; font-weight: 600; color: var(--text); }
.step-label + input { margin-top: 0; }
/* Leaderboard and Masters rows: rank (or trophy) | name + badge icons | points.
   Names never wrap; a long one ends in "…" so the points stay on the same line. */
.leaderboard-list, .masters-list { list-style: none; padding: 0; margin: 0; }
.lb-row { display: grid; grid-template-columns: 1.6em minmax(0, 1fr) auto; align-items: center; gap: 8px; margin: 7px 0; }
.lb-rank { color: var(--muted); font-weight: 700; text-align: right; }
.lb-who { display: flex; align-items: center; gap: 0; min-width: 0; white-space: nowrap; }
.lb-name { overflow: hidden; text-overflow: ellipsis; margin-right: 4px; }
.lb-who .lb-badge { flex-shrink: 0; display: inline-flex; }
.lb-row .lb-score { color: var(--muted); white-space: nowrap; text-align: right; }
.leaderboard-list .empty, .masters-list .empty { color: var(--muted); }
/* A long Masters list scrolls inside its card instead of making the side cards taller */
.masters-list { max-height: 15em; overflow-y: auto; padding-right: 6px; }

/* Masters: players who earned all three badges */
.masters { border: 2px solid var(--medium); }
.masters h3 { margin-top: 0; }

/* "Earn all 3 badges" note, pinned to the bottom of the Masters card */
.master-goal { margin-top: auto; padding-top: 14px; text-align: center; color: var(--muted); font-weight: 600; }
.master-goal p { margin: 0 0 8px; }
.master-badges { display: flex; justify-content: center; gap: 14px; font-size: 1.6em; }
.master-badges .badge-icon { margin: 0; }
.master-shimmer {
  font-weight: 800;
  background: linear-gradient(100deg, var(--medium) 0%, var(--medium) 40%, #fff8d6 50%, var(--medium) 60%, var(--medium) 100%);
  background-size: 250% 100%;
  -webkit-background-clip: text; background-clip: text;
  color: transparent;
  animation: master-shimmer 2.6s linear infinite;
}
@keyframes master-shimmer {
  from { background-position: 100% 0; }
  to   { background-position: -150% 0; }
}

/* Mission screen */
.briefing { margin-top: 0; line-height: 1.6; color: var(--muted); }
.briefing p { margin: 0 0 10px; }
.briefing p:last-child { margin-bottom: 0; }
.briefing b { color: var(--text); }
.briefing-title { font-size: 13px; font-weight: 600; letter-spacing: 2px; text-transform: uppercase; color: var(--teal) !important; }
.mission-mode { font-size: 20px; font-weight: 800; color: var(--text); }
.mission-mode.tier-easy, .mission-mode.tier-medium, .mission-mode.tier-hard { color: var(--tier); }
.facts { padding: 10px 14px; border-left: 3px solid var(--teal); background: rgba(45, 224, 196, 0.08); border-radius: 6px; }
.mission-buttons { display: flex; justify-content: space-between; align-items: flex-end; gap: 12px; }
button.secondary { background: transparent; color: var(--text); border: 2px solid var(--navy-2); }

input {
  display: block; width: 100%; margin: 0; padding: 12px;
  border-radius: 10px; border: 1px solid var(--navy-2);
  background: var(--navy-2); color: var(--text); font-size: 1rem;
}

button {
  font-family: inherit; font-size: 1rem; font-weight: 600; line-height: normal; cursor: pointer;
  border: none; border-radius: 10px; padding: 12px 18px;
  background: var(--teal); color: var(--navy);
}
button:disabled { opacity: 0.5; cursor: default; }

/* Start mission is a little fishing boat that blinks a teal glow to draw the eye.
   The button itself is see-through: ::before is the hull, ::after the cabin
   and mast. The glow is a drop-shadow so it follows the boat's outline
   instead of a rectangle. It's big, so the mission screen's gaps are trimmed
   (see "Mission screen" below) to keep everything on one screen; the mast
   tip pokes a little above the button into the gap. */
#btn-start {
  position: relative; isolation: isolate;
  min-width: 300px; padding: 30px 64px 12px; border-radius: 0;
  font-size: 1.35rem; font-weight: 800; letter-spacing: 0.5px;
  background: transparent; color: var(--navy);
  animation: start-blink 1.4s ease-in-out infinite;
}
#btn-start::before { /* hull, with a darker stripe at the waterline */
  content: ""; position: absolute; inset: 20px 0 0 0; z-index: -1;
  background: linear-gradient(var(--teal) 82%, #1fa892 82%);
  clip-path: polygon(0 6%, 100% 0, 89% 100%, 8% 100%);
}
#btn-start::after { /* cabin with a porthole (left) and the mast (right) */
  content: ""; position: absolute; left: 24%; bottom: calc(100% - 20px);
  width: 40%; max-width: 140px; height: 30px;
  background:
    radial-gradient(circle, var(--navy-2) 3.5px, transparent 4.5px) no-repeat left calc(27% - 6px) bottom 2px / 12px 12px,
    linear-gradient(var(--text), var(--text)) no-repeat right 20% bottom / 4px 30px,
    linear-gradient(var(--text), var(--text)) no-repeat left bottom / 55% 16px;
}
#btn-start:hover, #btn-start:focus-visible { animation: none; filter: brightness(1.1) drop-shadow(0 0 10px rgba(45, 224, 196, 0.6)); }
@keyframes start-blink {
  0%, 100% { filter: brightness(1) drop-shadow(0 0 0 rgba(45, 224, 196, 0)); }
  50% { filter: brightness(1.15) drop-shadow(0 0 12px rgba(45, 224, 196, 0.85)); }
}

.modes { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; }
/* Each difficulty sets --tier; anything tagged with it (icons, the mission title) uses that color */
.tier-easy { --tier: var(--easy); --tier-tint: var(--easy-tint); }
.tier-medium { --tier: var(--medium); --tier-tint: var(--medium-tint); }
.tier-hard { --tier: var(--hard); --tier-tint: var(--hard-tint); }
.tier-easy, .tier-medium, .tier-hard { color: var(--tier); }

/* Badge icon: sized to the text around it, drawn in currentColor */
.badge-icon { display: inline-block; width: 1.15em; height: 1.15em; vertical-align: -0.2em; margin-right: 0.3em; }
.badge-label { white-space: nowrap; }

/* Difficulty buttons: colored border, light tint on hover, text stays white on the dark card */
button.mode {
  padding: 18px 8px; background: var(--navy-2); color: var(--text); border: 2px solid var(--tier);
  transition: background-color 0.15s ease;
}
button.mode:hover, button.mode:focus-visible {
  background: linear-gradient(var(--tier-tint), var(--tier-tint)) var(--navy-2);
}
button.mode:focus-visible { outline: 2px solid var(--tier); outline-offset: 2px; }
.mode .badge-icon { width: 1.3em; height: 1.3em; vertical-align: -0.3em; }
.mode small { color: var(--muted); font-weight: 400; }

/* Our card style (named ps-card so Bootstrap's .card doesn't restyle it) */
.ps-card { background: var(--navy-2); border-radius: 14px; padding: 18px; margin: 16px 0; }
.ps-card.good { border-left: 6px solid var(--green); }
.ps-card.bad { border-left: 6px solid var(--red); }

.loading { color: var(--muted); text-align: center; padding: 24px; }

/* ---------- Play layout (Bootstrap grid: col-lg-7 message, col-lg-5 answers) ---------- */
#play-screen .ps-card { margin: 0; }
.message-wrap { position: relative; }
#result h3 { margin-top: 0; }
#result p:last-child, #result ul:last-child { margin-bottom: 0; }

/* Phones and narrow windows: one column.
   The answer column's box is dissolved so its pieces stack under the message
   (buttons, reaction, result, Next), and the contacts panel can move to the top. */
@media (max-width: 991.98px) {
  .play-side { display: contents; }
  #play-screen .play-side > * {
    flex-shrink: 0;
    width: calc(100% - var(--bs-gutter-x));
    margin: var(--bs-gutter-y) calc(var(--bs-gutter-x) * 0.5) 0;
  }
  #play-screen #contacts-panel { order: -1; }   /* opens right under the top bar */
}

/* Large screens: two columns, sized so a whole round fits without scrolling */
@media (min-width: 992px) {
  :root { --fit-h: calc(100vh - 104px); }
  @supports (height: 100dvh) { :root { --fit-h: calc(100dvh - 104px); } }

  .play-side { display: flex; flex-direction: column; gap: 12px; max-height: var(--fit-h); }
  .play-side > * { flex: 0 0 auto; }
  .contacts-panel .contacts-table th, .contacts-panel .contacts-table td { padding: 6px; }

  /* Long explanations scroll inside the card, so Next stays on screen */
  #result.ps-card { flex: 0 1 auto; min-height: 0; overflow-y: auto; padding: 14px 16px; font-size: 15px; line-height: 1.45; }
  #result ul { padding-left: 20px; margin: 6px 0 10px; }
  #result li { margin: 3px 0; }
  #result p { margin: 8px 0; }

  .answer { padding: 18px; font-size: 18px; }
  #btn-next { width: 100%; margin: 0; }

  /* Long messages scroll inside the message, never the page */
