@media (min-width: 900px) {
  /* About 25% / 50% / 25% */
  .home-grid { grid-template-columns: minmax(0, 1fr) minmax(0, 2fr) minmax(0, 1fr); gap: 24px; align-items: stretch; }
  .home-board { order: 1; }
  .home-center { order: 2; }
  .home-masters { order: 3; }

  /* The home screen fills the window: header on top, then the three columns
     stretch down to just above the waves. The center content sits in the middle
     of its column, and its gaps and buttons grow a little on taller screens. */
  body[data-screen="start-screen"] { display: flex; flex-direction: column; min-height: 100vh; min-height: 100dvh; }
  body[data-screen="start-screen"] main {
    flex: 1 0 auto; width: 100%; display: flex; flex-direction: column;
    padding-bottom: max(16px, 9vh);   /* stop at the top of the waves */
  }
  body[data-screen="start-screen"] .home-grid { flex: 1 0 auto; }
  .home-center { display: flex; flex-direction: column; justify-content: center; }
  .home-center .step-label { margin-top: clamp(16px, 3.6vh, 40px); }
  .home-center input { padding: 16px 18px; font-size: 1.2rem; }
  button.mode { min-height: clamp(112px, 12vh, 132px); font-size: 1.2rem; }
  .mode .badge-icon { width: 1.6em; height: 1.6em; vertical-align: -0.45em; }
  .mode small { font-size: 0.8em; }
  .home-center .master-goal { margin-top: clamp(16px, 3.2vh, 36px); }
}
/* Wide screens: the home screen uses a little more width */
@media (min-width: 1400px) {
  body[data-screen="start-screen"] main.container { max-width: 1320px; }
}

