// Minimal static server for testing: node serve.cjs <dir> <port>
const http = require("http"), fs = require("fs"), path = require("path");
const root = path.resolve(process.argv[2]), port = Number(process.argv[3] || 5517);
const types = { ".html": "text/html", ".js": "text/javascript", ".css": "text/css", ".svg": "image/svg+xml", ".png": "image/png", ".json": "application/json" };
http.createServer((req, res) => {
  const p = path.join(root, decodeURIComponent(req.url.split("?")[0]).replace(/\/$/, "/index.html"));
  if (!p.startsWith(root)) return res.writeHead(403).end();
  fs.readFile(p, (err, buf) => {
    if (err) return res.writeHead(404).end("not found");
    res.writeHead(200, { "Content-Type": types[path.extname(p)] || "application/octet-stream", "Cache-Control": "no-store" }).end(buf);
  });
}).listen(port, "127.0.0.1", () => console.log(`serving ${root} on ${port}`));

